CREATE OR REPLACE FUNCTION public.pay_waffo_close_uncreated(p_user uuid, p_order uuid, p_merchant text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE o payment_orders;
BEGIN
 PERFORM 1 FROM profiles WHERE id=p_user FOR UPDATE;
 SELECT * INTO o FROM payment_orders WHERE id=p_order AND user_id=p_user FOR UPDATE;
 IF o.id IS NULL OR o.payment_channel IS DISTINCT FROM 'stripe' OR NOT pay_method_mode_allowed(o.payment_channel,o.payment_mode)
  OR o.merchant_namespace IS DISTINCT FROM p_merchant OR o.payment_method NOT IN ('wechat_pay','alipay','card','card_cn')
